/* Bonus 11 — adapté du support 谈交通.pptx. Itinéraires, horaires et disponibilités fictifs.
 * Une écoute par réplique, pause, production guidée et réactivation espacée.
 * Les exercices reprennent chaque phrase distincte puis cinq variantes inédites.
 */
function transportExerciseWords(text){
 const words=["公共汽车","公共厕所","交通工具","长途汽车","不好意思","飞机场","火车站","地铁站","火车票","登机牌","登机口","航站楼","自行车","出租车","摩托车","私家车","头等舱","经济舱","始发站","终点站","红绿灯","一点儿","早点儿","有时候","星期五","星期天","星期六","星期一","电影院","市中心","东大街","地铁票","上海","北京","中心","公共","汽车","地铁","方便","便宜","平时","上班","经常","什么","工具","今天","下雨","我们","你们","他们","不过","附近","学校","公园","怎么","哪儿","这里","那里","这儿","那儿","那么","这么","走路","分钟","小时","邻近","城市","时候","单程","往返","出发","上午","下午","明天","乘客","可以","多少","还是","火车","硬座","软座","卧铺","证件","夜车","睡觉","座位","已经","没有","车票","医院","门口","宾馆","换乘","方向","以后","以前","银行","左边","右边","上面","路口","路牌","标志","写着","司机","师傅","地址","旅行","打算","工作","堵车","现在","路上","大概","需要","时间","估计","至少","如果","应该","知道","麻烦","厕所","前面","调头","谢谢","地方","行李","机票","航班","回来","护照","号码","机场","箱子","等候","飞机","起飞","开始","登机","准备","托运"];
 words.unshift('乘坐');
 const source=String(text).replace(/[。！？!?]$/u,'');
 const tokens=[];
 for(let i=0;i<source.length;){
  if(/[，。！？；：、]/u.test(source[i])){if(tokens.length) tokens[tokens.length-1]+=source[i];i++;continue;}
  if(/\s/u.test(source[i])){i++;continue;}
  const word=words.find(w=>source.startsWith(w,i)) || source.slice(i).match(/^[零一二两三四五六七八九十百千万]+/u)?.[0] || source[i];
  tokens.push(word);i+=word.length;
 }
 return tokens;
}
